from __future__ import annotations

import json
import secrets
from hmac import compare_digest
from pathlib import Path
from urllib.parse import quote, urlencode

import httpx

from .config import get_settings, oauth_state_path, tokens_path
from .models import Draft

AUTH_URL = "https://www.linkedin.com/oauth/v2/authorization"
TOKEN_URL = "https://www.linkedin.com/oauth/v2/accessToken"
UGC_URL = "https://api.linkedin.com/v2/ugcPosts"
USERINFO_URL = "https://api.linkedin.com/v2/userinfo"


class PublishError(RuntimeError):
    pass


def authorization_url() -> str:
    settings = get_settings()
    if not settings.linkedin_client_id:
        raise PublishError("Set LINKEDIN_CLIENT_ID in .env first.")
    state = secrets.token_urlsafe(32)
    oauth_state_path().write_text(state, encoding="utf-8")
    query = urlencode(
        {
            "response_type": "code",
            "client_id": settings.linkedin_client_id,
            "redirect_uri": settings.linkedin_redirect_uri,
            "scope": settings.linkedin_scopes.strip(),
            "state": state,
        },
        quote_via=quote,
    )
    return f"{AUTH_URL}?{query}"


def exchange_code(code: str, state: str = "") -> dict:
    settings = get_settings()
    expected_state_path = oauth_state_path()
    expected_state = expected_state_path.read_text(encoding="utf-8").strip() if expected_state_path.exists() else ""
    if not state or not expected_state or not compare_digest(state, expected_state):
        raise PublishError("OAuth state did not match. Start authorization again.")
    data = {
        "grant_type": "authorization_code",
        "code": code,
        "redirect_uri": settings.linkedin_redirect_uri,
        "client_id": settings.linkedin_client_id,
        "client_secret": settings.linkedin_client_secret,
    }
    with httpx.Client(timeout=30.0) as client:
        response = client.post(TOKEN_URL, data=data)
        if response.status_code >= 400:
            raise PublishError(f"LinkedIn token exchange failed ({response.status_code}).")
        payload = response.json()
    tokens_path().write_text(json.dumps(payload, indent=2), encoding="utf-8")
    expected_state_path.unlink(missing_ok=True)
    return payload


def load_tokens() -> dict:
    path = tokens_path()
    if not path.exists():
        raise PublishError("No OAuth token. Open the Setup page and authorize first.")
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except json.JSONDecodeError as exc:
        raise PublishError("The local OAuth token file is invalid.") from exc


def person_urn(access_token: str) -> str:
    settings = get_settings()
    if settings.linkedin_person_urn:
        return settings.linkedin_person_urn
    headers = {"Authorization": f"Bearer {access_token}"}
    with httpx.Client(timeout=30.0) as client:
        response = client.get(USERINFO_URL, headers=headers)
        if response.status_code >= 400:
            raise PublishError(f"LinkedIn user lookup failed ({response.status_code}).")
        data = response.json()
    subject = data.get("sub")
    if not subject:
        raise PublishError("LinkedIn user lookup did not return a member subject.")
    return f"urn:li:person:{subject}"


def ugc_payload(draft: Draft, author: str) -> dict:
    return {
        "author": author,
        "lifecycleState": "PUBLISHED",
        "specificContent": {
            "com.linkedin.ugc.ShareContent": {
                "shareCommentary": {"text": draft.body.strip()},
                "shareMediaCategory": "NONE",
            }
        },
        "visibility": {"com.linkedin.ugc.MemberNetworkVisibility": "PUBLIC"},
    }


def publish_draft(draft: Draft, *, live: bool = False, confirmed: bool = False) -> dict:
    """Publish only after a local approval and an explicit user action.

    `live=True` is never called by research or drafting automation. The UI publish
    button and CLI `--live` are the deliberate last-mile actions.
    """
    if draft.meta.status != "approved":
        raise PublishError(f"Refusing to publish status={draft.meta.status}. Approve the draft first.")
    if draft.meta.published_id:
        raise PublishError("This draft already has a LinkedIn publication ID.")
    if not confirmed:
        raise PublishError("Publishing requires an explicit confirmation action.")
    settings = get_settings()
    if not live:
        author = settings.linkedin_person_urn or "urn:li:person:DRY_RUN"
        return {"dry_run": True, "url": UGC_URL, "payload": ugc_payload(draft, author)}
    if not settings.live_publish_enabled:
        raise PublishError("Set LINKEDIN_LIVE_PUBLISH=1 to enable the explicit publish button.")
    tokens = load_tokens()
    access_token = str(tokens.get("access_token") or "")
    if not access_token:
        raise PublishError("The local OAuth token has no access_token.")
    author = person_urn(access_token)
    payload = ugc_payload(draft, author)
    headers = {
        "Authorization": f"Bearer {access_token}",
        "Content-Type": "application/json",
        "X-Restli-Protocol-Version": "2.0.0",
    }
    with httpx.Client(timeout=30.0) as client:
        response = client.post(UGC_URL, headers=headers, json=payload)
    if response.status_code >= 400:
        raise PublishError(f"LinkedIn publishing failed ({response.status_code}).")
    post_id = response.headers.get("x-restli-id") or response.headers.get("X-RestLi-Id") or ""
    if not post_id:
        raise PublishError("LinkedIn accepted the request but returned no publication ID.")
    return {"dry_run": False, "id": post_id, "status_code": response.status_code}


def token_file() -> Path:
    return tokens_path()
